from collect import *
rows=[]
def add(title,area,url,year,loc,author,**kw):rows.append(dict(title=title,area=area,source_url=url,source_collection=kw.pop('collection','Landmark reference'),source_year=str(year),source_locator=loc,authors=author,status=kw.pop('status','source_open_unverified'),status_note=kw.pop('note','Standard open problem stated in the cited reference; later literature not exhaustively checked.'),scope='landmark',accessed='2026-09-09',**kw))
add('P versus NP','Computational and circuit complexity','https://www.claymath.org/millennium/p-vs-np/','2026','Millennium Prize Problem','Clay Mathematics Institute',status='maintainer_lists_open',note='Listed among CMI’s unsolved Millennium Prize Problems when accessed 2026-09-09.',question='Can every problem whose solutions are efficiently verifiable also be solved in polynomial time?')
u='https://www.math.ias.edu/files/mathandcomp.pdf';t=fetch(u)['text']
items=[('3.8','NP versus coNP','Computational and circuit complexity'),('3.9','P versus NP intersect coNP','Computational and circuit complexity'),('4.3','Unique Games Conjecture','Approximation algorithms'),('4.5','Worst-case versus average-case NP hardness','Average-case complexity'),('4.9','One-way functions from NP hardness','Cryptography'),('5.4','Polynomial-size circuits for NP','Computational and circuit complexity'),('5.7','Exponential circuit lower bounds for SAT','Computational and circuit complexity'),('5.8','Explicit superlinear Boolean circuit lower bounds','Computational and circuit complexity'),('5.11','Polynomial formulas versus linear circuits','Computational and circuit complexity'),('5.13','Kronecker-style formula composition lower bounds','Computational and circuit complexity'),('5.19','Cubic monotone formulas for majority','Computational and circuit complexity'),('6.10','Superpolynomial Frege proof lower bounds','Proof complexity and logic'),('6.12','Frege lower bounds from circuit hardness','Proof complexity and logic'),('7.5','P versus BPP','Pseudorandomness and derandomization'),('8.6','Polynomial-size circuits for EXP','Computational and circuit complexity'),('11.4','BPP versus BQP','Quantum computation'),('11.5','NP outside BQP','Quantum computation'),('12.1','Explicit univariate arithmetic circuit lower bounds','Algebraic and numerical computation'),('12.4','Superlinear constant-degree arithmetic circuit lower bounds','Algebraic and numerical computation'),('12.13','Matrix multiplication exponent two','Algebraic and numerical computation'),('12.21','VP versus VNP','Algebraic and numerical computation'),('14.7','L versus BPL','Pseudorandomness and derandomization'),('14.8','L versus NL','Computational and circuit complexity'),('15.34','Efficient explicit constant-rate tree codes','Coding and information theory'),('17.9','Learning growing-size DNFs under uniform inputs','Learning theory')]
for num,title,area in items:
 if num=='5.13':title='Karchmer–Raz–Wigderson formula composition conjecture'
 m=re.search(r'(?m)^\s*(Open Problem|Conjecture) '+re.escape(num)+r'\b',t);assert m,num
 add(title,area,u,2018,m.group(1)+' '+num,'Avi Wigderson',collection='Mathematics and Computation (2018 draft)',pdf_url=u+'#page='+str(t[:m.start()].count('\f')+1))
u='https://www.scottaaronson.com/papers/open.pdf';t=fetch(u)['text']
Q={2:'Oracle separation between QMA and QMA(2)',3:'Quantum query–space tradeoffs for collisions and distinctness',4:'Maximum randomized-versus-quantum gap for total functions',5:'Quantum query complexity versus bounded approximate degree',6:'Black-box unitary synthesis',7:'Oracle separation of BQP from IP',8:'Oracle separation of BQP from efficient-prover interactive proofs',10:'Quantum hardness of finding an entire glued-tree path',11:'Injective quantum oracles: standard versus erasing access',12:'Query complexity of high-score cross-entropy sampling'}
for n,title in Q.items():
 m=re.search(r'(?m)^Problem '+str(n)+r'\b',t);assert m
 add(title,'Quantum computation',u,2021,'Problem '+str(n),'Scott Aaronson',collection='Open Problems Related to Quantum Query Complexity',pdf_url=u+'#page='+str(t[:m.start()].count('\f')+1))
(ROOT/'landmark_rows.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2));print('LANDMARK',len(rows))
